<?php
require_once 'config.php';require_once 'includes/db.php';require_once 'includes/functions.php';$db=getDB();$error='';$ok='';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$email=filter_var(clean($_POST['email']??''),FILTER_VALIDATE_EMAIL);$otp=clean($_POST['otp']??'');$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';
if(!$email||!$otp||strlen($p)<8||$p!==$c){$error='Invalid input.';}else{$st=$db->prepare('SELECT id,otp_code,otp_expires FROM users WHERE email=?');$st->execute([$email]);$u=$st->fetch();if(!$u||!$u['otp_code']||strtotime($u['otp_expires'])<time()||!password_verify($otp,$u['otp_code'])){$error='Invalid or expired OTP.';}else{$h=password_hash($p,PASSWORD_BCRYPT,['cost'=>12]);$db->prepare('UPDATE users SET password_hash=?, otp_code=NULL, otp_expires=NULL WHERE id=?')->execute([$h,$u['id']]);setFlash('success','Password reset successful. Please login.');header('Location: login.php');exit;}}}
$pageTitle='Reset Password';require_once 'includes/header.php'; ?>
<div class="page-container section"><div class="card" style="max-width:500px;margin:auto"><h2>Reset Password</h2><?php if($error): ?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="email" name="email" placeholder="Email" required><input name="otp" placeholder="OTP" required><input type="password" name="password" placeholder="New Password" required><input type="password" name="confirm_password" placeholder="Confirm Password" required><button class="btn-primary">Reset Password</button></form></div></div>
